using HotChocolate.Authorization;
using GraphApi.Infrastructure.Services;using GraphApi.Models.SGR.MenusBotones;using GraphApi.Services.SGR.MenusBotones;using HotChocolate;using System.Linq;namespace GraphApi.GraphQL.SGR.MenusBotones{    [MutationType]    [GraphQLDescription("Punto de entrada para las mutaciones de MenusBotones: creación, actualización y eliminación.")]    public class MenusBotonesMutation    {        [Authorize]        [GraphQLName("createMenusBotones")]        [GraphQLDescription("Crea un nuevo MenusBotone usando los headers 'UserID' y 'WindowName'.")]        public async Task<clReadMenusBotones> CreateMenusBotonesAsync(            [GraphQLDescription("Datos necesarios para crear el MenusBotone.")]            clCreateMenusBotones objInput,            [Service]            [GraphQLDescription("Servicio para operaciones de MenusBotone.")]            IMenusBotonesService objService,
            [Service] IGraphQLContextService objCtx        )        {            var (userId, windowName) = objCtx.GetRequestContext();            return await objService.CreateMenusBotones(objInput, userId, windowName);        }        [Authorize]        [GraphQLName("updateMenusBotones")]        [GraphQLDescription("Actualiza los campos especificados de un MenusBotone existente.")]        public async Task<clReadMenusBotones?> UpdateMenusBotonesAsync(            [GraphQLDescription("Datos del MenusBotone a actualizar.")]            clUpdateMenusBotones objInput,            [Service]            [GraphQLDescription("Servicio para operaciones de MenusBotone.")]            IMenusBotonesService objService,
            [Service] IGraphQLContextService objCtx        )        {            var (userId, windowName) = objCtx.GetRequestContext();            return await objService.UpdateMenusBotones(objInput, userId, windowName);        }        [Authorize]        [GraphQLName("deleteMenusBotones")]        [GraphQLDescription("Elimina un MenusBotone por su ID.")]        public async Task<bool> delMenusBotonesAsync(            [GraphQLDescription("ID del MenusBotone a eliminar.")]            int nMenusBotonesID,            [Service]            [GraphQLDescription("Servicio para operaciones de MenusBotone.")]            IMenusBotonesService objService        )        {            return await objService.DeleteMenusBotones(nMenusBotonesID);        }    }}